def esc(s):
    return s.replace('\\','\\\\').replace('(','\\(').replace(')','\\)').replace('—','-').replace('–','-').replace('→','>').replace('·','|').replace('“','"').replace('”','"').replace('’',"'").replace('‘',"'")
def rgb(c): return ' '.join(f'{x:.3f}' for x in c)
def txt(x,y,s,size=10,color=INK,font='F1'):
    return f'BT /{font} {size} Tf {rgb(color)} rg 1 0 0 1 {x:.1f} {y:.1f} Tm ({esc(s)}) Tj ET\n'
def wrap(s,n): return textwrap.wrap(s,width=n,break_long_words=False,break_on_hyphens=False) or ['']
def page_content(p,n):
    title,kicker,lead,sub,body,callout,meta=p; c=''
    c+=f'{rgb(BLUE)} rg 0 {H-8} {W} 8 re f\n'+txt(M,H-42,'KNOWLEDGE CONTINUITY',8,BLUE,'F2')+txt(W-M-90,H-42,f'ROUND 1   /   {n:02d}',8,MUTED,'F2')
    c+=f'{rgb(PALE)} RG 1 w {M} {H-55} m {W-M} {H-55} l S\n'+txt(M,H-86,kicker,8,TEAL,'F2')
    y=H-126
    for t in wrap(title,43): c+=txt(M,y,t,25,NAVY,'F2'); y-=31
    y-=17
    for t in wrap(lead,49): c+=txt(M,y,t,15,BLUE,'F2'); y-=21
    y-=18
    if sub:
        c+=txt(M,y,sub,11,MUTED); y-=30
    for label,para in body:
        c+=txt(M,y,label.upper(),8,TEAL,'F2'); y-=15
        for t in wrap(para,91): c+=txt(M,y,t,9.4,INK); y-=13
        y-=11
    lines=wrap(callout,92); bh=26+14*len(lines); by=max(83,y-bh-4)
    c+=f'{rgb(PALE)} rg {M} {by} {W-2*M} {bh} re f\n{rgb(TEAL)} rg {M} {by} 4 {bh} re f\n'
    ty=by+bh-20
    for t in lines: c+=txt(M+15,ty,t,9,NAVY,'F2'); ty-=14
    c+=f'{rgb(PALE)} RG 1 w {M} 55 m {W-M} 55 l S\n'+txt(M,37,meta,7,MUTED)+txt(W-M-28,37,f'{n:02d}',8,BLUE,'F2')
    return c.encode('latin-1','replace')

objs=[]
def add(o): objs.append(o); return len(objs)
f1=add(b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'); f2=add(b'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'); pid=add(b''); kids=[]
for i,p in enumerate(PAGES,1):
    s=page_content(p,i); cid=add(b'<< /Length '+str(len(s)).encode()+b' >>\nstream\n'+s+b'endstream')
    kids.append(add(f'<< /Type /Page /Parent {pid} 0 R /MediaBox [0 0 {W} {H}] /Resources << /Font << /F1 {f1} 0 R /F2 {f2} 0 R >> >> /Contents {cid} 0 R >>'.encode()))
objs[pid-1]=f'<< /Type /Pages /Kids [{" ".join(f"{k} 0 R" for k in kids)}] /Count {len(kids)} >>'.encode()
root=add(f'<< /Type /Catalog /Pages {pid} 0 R >>'.encode())
pdf=bytearray(b'%PDF-1.4\n%\xe2\xe3\xcf\xd3\n'); offs=[0]
for i,o in enumerate(objs,1): offs.append(len(pdf)); pdf.extend(f'{i} 0 obj\n'.encode()+o+b'\nendobj\n')
xref=len(pdf); pdf.extend(f'xref\n0 {len(objs)+1}\n0000000000 65535 f \n'.encode())
for off in offs[1:]: pdf.extend(f'{off:010d} 00000 n \n'.encode())
pdf.extend(f'trailer\n<< /Size {len(objs)+1} /Root {root} 0 R >>\nstartxref\n{xref}\n%%EOF\n'.encode())
OUT.write_bytes(pdf)
print(f'Wrote {OUT} ({len(pdf)} bytes, {len(PAGES)} pages)')
